"""Package file with the generated `knx:` configuration."""

from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml

from .const import DOMAIN
from .mapping.manifest import HA_DOMAINS, unique_id_for
from .model import OwnEntities

HEADER = f"""\
# Automatisch erzeugt von {DOMAIN} – nicht von Hand bearbeiten.
# Generated by {DOMAIN} – do not edit, changes are overwritten on the next import.
# Projekt / project: {{project}}
"""


def render(knx: dict[str, list[dict[str, Any]]], project: str | None) -> str:
    body = yaml.safe_dump(
        {"knx": knx} if knx else {"knx": {}},
        allow_unicode=True,
        sort_keys=False,
        default_flow_style=False,
        width=1000,
    )
    return HEADER.format(project=project or "-") + body


def write(path: Path, content: str) -> None:
    """Write atomically (runs in the executor)."""
    from homeassistant.util.file import write_utf8_file_atomic

    path.parent.mkdir(parents=True, exist_ok=True)
    write_utf8_file_atomic(str(path), content)


def read_unique_ids(path: Path) -> set[tuple[str, str]]:
    """unique_ids defined by the package file (runs in the executor)."""
    if not path.exists():
        return set()
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    return unique_ids_of_knx_config(data.get("knx") or {})


def _plain(value: Any) -> Any:
    """Plain Python types (HA's YAML loader returns str/dict/list subclasses with line info)."""
    if isinstance(value, dict):
        return {str(k): _plain(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_plain(v) for v in value]
    if isinstance(value, bool) or value is None:
        return value
    for kind in (int, float, str):
        if isinstance(value, kind):
            return kind(value)
    return str(value)


def _first(value: Any) -> Any:
    """Raw YAML allows a single address or a list (first = sending address)."""
    if isinstance(value, list):
        return value[0] if value else None
    return value


def unique_ids_of_knx_config(knx: dict[str, Any]) -> set[tuple[str, str]]:
    """(domain, unique_id) of all entities in a raw (not validated) `knx:` config."""
    return set(entities_of_knx_config(knx))


def entities_of_knx_config(knx: dict[str, Any]) -> OwnEntities:
    """(domain, unique_id) -> {"config", "file", "line"} of a raw `knx:` config.

    `file` and `line` come from Home Assistant's YAML loader (None for plain dicts).
    """
    out: OwnEntities = {}
    for domain in HA_DOMAINS:
        items = knx.get(domain) or []
        if isinstance(items, dict):
            items = [items]
        for item in items:
            if not isinstance(item, dict):
                continue
            config = {k: _first(v) if k.endswith("address") or k.startswith("address_") else v for k, v in item.items()}
            try:
                uid = unique_id_for(domain, config)
            except (TypeError, ValueError):
                continue
            out.setdefault(
                (domain, uid),
                {
                    "config": _plain(item),
                    "file": getattr(item, "__config_file__", None),
                    "line": getattr(item, "__line__", None),
                },
            )
    return out
